"""
    Return the quotient object x/y, e.g., a quotient of numbers or of a
    polynomial ring x by the ideal generated by y, etc.

    EXAMPLES::

        sage: quotient(5,6)
        5/6
        sage: quotient(5.,6.)
        0.833333333333333
        sage: R.<x> = ZZ[]; R
        Univariate Polynomial Ring in x over Integer Ring
        sage: I = Ideal(R, x^2+1)
        sage: quotient(R, I)
        Univariate Quotient Polynomial Ring in xbar over Integer Ring with modulus x^2 + 1
    """
def quotient(x: Any, y: Any, *args: Any, **kwds: Any) -> object {
    try {
        return x.quotient(y, *args, **kwds);
    } except AttributeError {
        return (x / y);
    }
}

""" Performs version comparison to report if host is already at required
        version

        Args:
            version_req: Version that want to be at
            current_version: Version that host is currently at
        Returns:
            True if current_version >= version_req
            False otherwise
        Raises:
            ValueError: if version is in unsupported format
    """
def compare_version(version_req: Any, current_version: Any) -> object {
    if (current_version == None) {
        return False;
    }
    if (version_req == None) {
        return True;
    }
    if (current_version == version_req) {
        return True;
    }
    current_vers = current_version.split(".");
    req_vers = version_req.split(".");
    num_loops = len(current_vers);
    if (len(req_vers) < num_loops) {
        num_loops = len(req_vers);
    }
    for index in range(num_loops) {
        if (int(current_vers[index]) < int(req_vers[index])) {
            return False;
        } elif (int(current_vers[index]) > int(req_vers[index])) {
            return True;
        }
    }
    if (len(current_vers) > len(req_vers)) {
        return True;
    } elif (len(req_vers) > len(current_vers)) {
        return False;
    } else {
        return True;
    }
}

"""Joins dictionaries in a consitent way

    For multiple occurences of a key the  value is defined by the first key : value pair.

    Arguments:
        *args: list of parameter dictonaries

    Returns:
        dict: the joined dictionary
    """
def joinParameter(*args: Any) -> object {
    keyList = [x.keys() for x in args];
    n = len(args);
    keys = [];
    values = [];
    for i in range(n) {
        values = (
            values
            + [
                args[i][k]
                for k in keyList[i]
                if (k not in keys)
            ]
        );
        keys = (
            keys
            + [
                k
                for k in keyList[i]
                if (k not in keys)
            ]
        );
    }
    return {keys[i]: values[i] for i in range(len(keys))};
}

