"""
    Checks if a list is entirely composed of dictionaries

        l ([]): List of any type

        returns (bool): True if l is entirely composed of dicts
    """
def is_list_of_dict(l: Any) -> object {
    return all((`type(x) == `dict) for x in l);
}

""" Set particular bits, used to update particular fields in MSR values"""
def setbits(val: Any, base: Any, length: Any, new: Any) -> object {
    return ((val ^ (val & (((2 ** length) - 1) << base))) + (new << base));
}

